SELECT * FROM payment_callback_event
WHERE 1 = 1
AND provider = #{query.provider}

    AND process_status = #{query.processStatus}

AND transaction_id = #{query.transactionId}

    AND provider_event_id ILIKE CONCAT('%', #{query.keyword}, '%')

ORDER BY received_at DESC, id DESC

SELECT * FROM payment_callback_event
WHERE provider = #{provider} AND provider_event_id = #{providerEventId}
ORDER BY id DESC LIMIT 1

SELECT * FROM payment_callback_event
WHERE provider = #{provider} AND provider_event_id = #{providerEventId}
  AND signature_verified = TRUE AND process_status IN ('RECEIVED', 'APPLIED')
